starter.css:
.progress {
  position: fixed;
  inset: 0 0 auto;
  height: 4px;
  background: #6d28d9;
  transform-origin: 0 50%;
}
.speakers { display: grid; gap: 16px; }
.speaker {
  padding: 40px 16px;
  border-radius: 12px;
  background: #f5f3ff;
}

@keyframes grow {
  from { scale: 0 1; }
  to { scale: 1 1; }
}
@keyframes reveal {
  from { opacity: 0; translate: 0 24px; }
  to { opacity: 1; translate: 0 0; }
}

/* A first attempt: why doesn't the bar move? */
.progress {
  animation-timeline: scroll(root);
  animation: grow linear both;
}

solution.css:
.progress {
  position: fixed;
  inset: 0 0 auto;
  height: 4px;
  background: #6d28d9;
  transform-origin: 0 50%;
}
.speakers { display: grid; gap: 16px; }
.speaker {
  padding: 40px 16px;
  border-radius: 12px;
  background: #f5f3ff;
}

@keyframes grow {
  from { scale: 0 1; }
  to { scale: 1 1; }
}
@keyframes reveal {
  from { opacity: 0; translate: 0 24px; }
  to { opacity: 1; translate: 0 0; }
}

@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .progress {
      animation: grow linear both;
      animation-timeline: scroll(root);
    }
    .speaker {
      animation: reveal linear both;
      animation-timeline: view();
      animation-range: entry 0% cover 30%;
    }
  }
}
